    "rules": [
      {
        "damageType": "{actor|flags.pf2e.dragonBloodline.damageType}",
        "diceNumber": "@item.level",
        "dieSize": "d4",
        "hideIfDisabled": true,
        "key": "DamageDice",
        "predicate": [
          "item:slug:flurry-of-claws",
          "feature:bloodline-draconic"
        ],
        "selector": "spell-damage"
      }
    ],
    "description": {
      "raw": "<p>Vicious dragon claws appear and slash at two nearby foes. Make a spell attack roll against each creature. This counts as two attacks for your multiple attack penalty, but the penalty doesn't increase until you've made both attacks. On a hit, the creatures takes 1d8 slashing plus 1d4 additional damage of a type determined by the magical tradition related to the dragon that influenced your bloodline: <strong>arcane</strong> force, <strong>divine</strong> spirit, <strong>occult</strong> mental, or <strong>primal</strong> fire.</p><hr /><p><strong>Heightened (+1)</strong> The initial damage increases by 1d8 and the additional damage increases by 1d4.</p>",
      "nodes": [
        {
          "kind": "TEXT",
          "value": "Vicious dragon claws appear and slash at two nearby foes. Make a spell attack roll against each creature. This counts as two attacks for your multiple attack penalty, but the penalty doesn't increase until you've made both attacks. On a hit, the creatures takes 1d8 slashing plus 1d4 additional damage of a type determined by the magical tradition related to the dragon that influenced your bloodline: arcane force, divine spirit, occult mental, or primal fire.\n\n---\nHeightened (+1) The initial damage increases by 1d8 and the additional damage increases by 1d4."
        }
      ]
    },
    "dependencyIds": []
