    "name": "Safe Passage",
    "category": "spell",
    "rank": 3,
    "rarity": "common",
    "traits": [
      "concentrate",
      "manipulate"
    ],
    "traditions": [
      "arcane",
      "divine",
      "primal"
    ],
    "time": "3",
