    "name": "Show the Path",
    "category": "spell",
    "rank": 4,
    "rarity": "uncommon",
    "traits": [
      "cleric",
      "concentrate",
      "focus",
      "fortune",
      "manipulate"
    ],
    "traditions": [],
    "time": "2",
