    "name": "Strange Geometry",
    "category": "spell",
    "rank": 5,
    "rarity": "common",
    "traits": [
      "concentrate",
      "illusion",
      "manipulate"
    ],
    "traditions": [
      "occult"
    ],
    "time": "3",
    "range": "60 feet",
