    "name": "Claim Undead",
    "category": "spell",
    "rank": 6,
    "rarity": "uncommon",
    "traits": [
      "concentrate",
      "focus",
      "incapacitation",
      "manipulate",
      "oracle"
    ],
    "traditions": [],
    "time": "2",
